#include <stdint.h>
#include <stddef.h>
uint16_t adc_average(const uint16_t *samples, size_t n) {
    uint16_t sum = 0;
    for (size_t i = 0; i < n; ++i) sum += samples[i];
    return (uint16_t)(sum / n);
}

